/* Shared testdata file attachment UI (Java MervTestDataFileHtml parity). Requires escHtml() in page scope. */
(function () {
  var PREVIEW_LINE_COUNT = 10;
  var OPEN_IN_TAB_LINE_THRESHOLD = 50;

  function fmtFileSize(n) {
    n = +n || 0;
    if (n < 1024) return n + ' B';
    if (n < 1048576) return (n / 1024).toFixed(2) + ' KB';
    return (n / 1048576).toFixed(2) + ' MB';
  }

  function isFlatExt(ext) {
    ext = String(ext || '').toLowerCase();
    if (!ext) return false;
    return ext === 'txt' || ext === 'json' || ext === 'csv' || ext === 'java';
  }

  function isImageExt(ext) {
    ext = String(ext || '').toLowerCase();
    if (!ext) return false;
    return (
      ext === 'png' ||
      ext === 'jpg' ||
      ext === 'jpeg' ||
      ext === 'gif' ||
      ext === 'bmp' ||
      ext === 'webp' ||
      ext === 'svg' ||
      ext === 'ico'
    );
  }

  function fileUrl(rel) {
    return ('../' + String(rel || '')).replace(/\\/g, '/');
  }

  function splitLines(t) {
    return String(t || '')
      .replace(/\r\n/g, '\n')
      .replace(/\r/g, '\n')
      .split('\n');
  }

  function renderOversizeFileBar(af) {
    var name = af.originalName || 'file';
    var ext = String(af.fileExtension || '').toUpperCase() || 'FILE';
    var size = fmtFileSize(af.fileSize);
    var h = '<div class="testdata-file-bar">';
    h += '<div class="testdata-file-bar-icon">&#128196;</div>';
    h +=
      '<div class="testdata-file-bar-info"><div class="testdata-file-bar-title"><span class="testdata-file-bar-name" title="' +
      escHtml(name) +
      '">' +
      escHtml(name) +
      '</span><span class="testdata-file-bar-badge">' +
      escHtml(ext) +
      '</span></div>';
    if (size) h += '<div class="testdata-file-bar-size">' + escHtml(size) + '</div>';
    h +=
      '<div class="testdata-file-bar-oversize">Download not available due to size exceed 20MB</div>';
    h += '</div></div>';
    return h;
  }

  function renderBinaryFileBar(af, url) {
    var name = af.originalName || 'file';
    var ext = String(af.fileExtension || '').toUpperCase() || 'FILE';
    var size = fmtFileSize(af.fileSize);
    var h = '<div class="testdata-file-bar">';
    h += '<div class="testdata-file-bar-icon">&#128196;</div>';
    h +=
      '<div class="testdata-file-bar-info"><div class="testdata-file-bar-title"><span class="testdata-file-bar-name" title="' +
      escHtml(name) +
      '">' +
      escHtml(name) +
      '</span><span class="testdata-file-bar-badge">' +
      escHtml(ext) +
      '</span></div>';
    if (size) h += '<div class="testdata-file-bar-size">' + escHtml(size) + '</div>';
    h += '</div><div class="testdata-file-bar-actions">';
    h +=
      '<button type="button" class="testdata-file-bar-btn" data-dl="' +
      escHtml(url) +
      '" data-name="' +
      escHtml(name) +
      '" title="Download">&#8681;</button>';
    h +=
      '<button type="button" class="testdata-file-bar-btn" data-open="' +
      escHtml(url) +
      '" title="Open in new tab">&#8599;</button>';
    h += '</div></div>';
    return h;
  }

  function renderImageFileBlock(af, url) {
    var name = af.originalName || 'file';
    return (
      '<div class="testdata-image-file"><img class="testdata-image-file-preview merv-zoomable-image" src="' +
      escHtml(url) +
      '" alt="' +
      escHtml(name) +
      '" loading="lazy" data-img-url="' +
      escHtml(url) +
      '" data-img-name="' +
      escHtml(name) +
      '" title="Click to zoom"/></div>'
    );
  }

  var _imgLbZoom = 1,
    _imgLbPanX = 0,
    _imgLbPanY = 0,
    _imgLbDrag = null;

  function applyImageLightboxTransform() {
    var img = document.querySelector('#merv-image-lightbox .merv-image-lightbox-img');
    if (img) img.style.transform = 'translate(' + _imgLbPanX + 'px,' + _imgLbPanY + 'px) scale(' + _imgLbZoom + ')';
  }

  function setImageLightboxZoom(z) {
    _imgLbZoom = Math.max(0.25, Math.min(4, z));
    applyImageLightboxTransform();
    var lbl = document.querySelector('#merv-image-lightbox .merv-image-lightbox-zoom-label');
    if (lbl) lbl.textContent = Math.round(_imgLbZoom * 100) + '%';
  }

  function resetImageLightboxView() {
    _imgLbZoom = 1;
    _imgLbPanX = 0;
    _imgLbPanY = 0;
    applyImageLightboxTransform();
    var lbl = document.querySelector('#merv-image-lightbox .merv-image-lightbox-zoom-label');
    if (lbl) lbl.textContent = '100%';
  }

  function wireImageLightboxDrag(vp) {
    if (vp._mervDragWired) return;
    vp._mervDragWired = true;
    vp.addEventListener('pointerdown', function (ev) {
      if (ev.button !== 0) return;
      _imgLbDrag = { sx: ev.clientX, sy: ev.clientY, px: _imgLbPanX, py: _imgLbPanY };
      vp.setPointerCapture(ev.pointerId);
      vp.classList.add('dragging');
      var img = vp.querySelector('.merv-image-lightbox-img');
      if (img) img.style.transition = 'none';
      ev.preventDefault();
    });
    vp.addEventListener('pointermove', function (ev) {
      if (!_imgLbDrag) return;
      _imgLbPanX = _imgLbDrag.px + (ev.clientX - _imgLbDrag.sx);
      _imgLbPanY = _imgLbDrag.py + (ev.clientY - _imgLbDrag.sy);
      applyImageLightboxTransform();
      ev.preventDefault();
    });
    var endLbDrag = function (ev) {
      if (!_imgLbDrag) return;
      _imgLbDrag = null;
      vp.classList.remove('dragging');
      var img = vp.querySelector('.merv-image-lightbox-img');
      if (img) img.style.transition = '';
      try {
        vp.releasePointerCapture(ev.pointerId);
      } catch (ex) {}
    };
    vp.addEventListener('pointerup', endLbDrag);
    vp.addEventListener('pointercancel', endLbDrag);
  }

  function closeImageLightbox() {
    var lb = document.getElementById('merv-image-lightbox');
    if (lb) lb.classList.remove('open');
  }

  function ensureImageLightbox() {
    var lb = document.getElementById('merv-image-lightbox');
    if (lb) return lb;
    lb = document.createElement('div');
    lb.id = 'merv-image-lightbox';
    lb.className = 'merv-image-lightbox';
    lb.innerHTML =
      '<div class="merv-image-lightbox-backdrop"></div><div class="merv-image-lightbox-panel"><div class="merv-image-lightbox-header"><span class="merv-image-lightbox-title"></span><button type="button" class="merv-image-lightbox-close" title="Close">&times;</button></div><div class="merv-image-lightbox-viewport"><img class="merv-image-lightbox-img" alt=""/></div><div class="merv-image-lightbox-toolbar"><button type="button" class="merv-image-lightbox-zoom-out" title="Zoom out">&#8722;</button><span class="merv-image-lightbox-zoom-label">100%</span><button type="button" class="merv-image-lightbox-zoom-in" title="Zoom in">+</button><button type="button" class="merv-image-lightbox-zoom-reset" title="Reset">Reset</button></div></div>';
    document.body.appendChild(lb);
    lb.querySelector('.merv-image-lightbox-backdrop').onclick = closeImageLightbox;
    lb.querySelector('.merv-image-lightbox-close').onclick = closeImageLightbox;
    lb.querySelector('.merv-image-lightbox-zoom-in').onclick = function () {
      setImageLightboxZoom(_imgLbZoom + 0.25);
    };
    lb.querySelector('.merv-image-lightbox-zoom-out').onclick = function () {
      setImageLightboxZoom(_imgLbZoom - 0.25);
    };
    lb.querySelector('.merv-image-lightbox-zoom-reset').onclick = resetImageLightboxView;
    wireImageLightboxDrag(lb.querySelector('.merv-image-lightbox-viewport'));
    return lb;
  }

  function openImageLightbox(url, name) {
    var lb = ensureImageLightbox();
    resetImageLightboxView();
    lb.querySelector('.merv-image-lightbox-title').textContent = name || 'Image';
    var img = lb.querySelector('.merv-image-lightbox-img');
    img.src = url;
    img.alt = name || 'Image';
    lb.classList.add('open');
  }

  function renderFlatFileBlock(af, url) {
    var id = 'flat-' + Math.random().toString(36).slice(2);
    var ext = String(af.fileExtension || '').toUpperCase() || 'FILE';
    var name = af.originalName || 'file';
    var h =
      '<div class="testdata-flat-file" id="' +
      id +
      '" data-url="' +
      escHtml(url) +
      '"><div class="testdata-flat-file-head"><span class="testdata-flat-file-name" title="' +
      escHtml(name) +
      '">' +
      escHtml(name) +
      '</span><span class="testdata-flat-file-badge">' +
      escHtml(ext) +
      '</span></div><pre class="testdata-flat-file-preview">Loading…</pre></div>';
    fetch(url)
      .then(function (r) {
        return r.text();
      })
      .then(function (txt) {
        var box = document.getElementById(id);
        if (!box) return;
        var pre = box.querySelector('.testdata-flat-file-preview');
        if (!pre) return;
        var lines = splitLines(txt);
        var preview = lines.slice(0, PREVIEW_LINE_COUNT).join('\n');
        pre.textContent = preview;
        box._fullText = txt;
        box._lineCount = lines.length;
        if (lines.length > PREVIEW_LINE_COUNT || lines.length > OPEN_IN_TAB_LINE_THRESHOLD) {
          var link = document.createElement('span');
          link.className = 'testdata-flat-file-link';
          link.textContent =
            lines.length > OPEN_IN_TAB_LINE_THRESHOLD
              ? 'Click to see full file (opens in new tab)'
              : 'Click to see full file';
          link.onclick = function (ev) {
            ev.preventDefault();
            if (box._lineCount > OPEN_IN_TAB_LINE_THRESHOLD) {
              window.open(url, '_blank');
              return;
            }
            pre.textContent = box._expanded ? preview : box._fullText;
            link.textContent = box._expanded ? 'Click to see full file' : 'Show less';
            box._expanded = !box._expanded;
          };
          box.appendChild(link);
        }
      })
      .catch(function () {
        var box = document.getElementById(id);
        if (!box) return;
        var pre = box.querySelector('.testdata-flat-file-preview');
        if (pre) pre.textContent = 'Could not load file preview.';
      });
    return h;
  }

  window.renderAttachedFiles = function (st) {
    var files = (st && st.attachedFiles) || [];
    if (!files.length) return '';
    var h = '<div class="testdata-files">';
    files.forEach(function (af) {
      if (!af) return;
      if (af.sizeExceeded) {
        h += renderOversizeFileBar(af);
        return;
      }
      if (!af.path) return;
      var url = fileUrl(af.path);
      if (isImageExt(af.fileExtension)) h += renderImageFileBlock(af, url);
      else if (isFlatExt(af.fileExtension)) h += renderFlatFileBlock(af, url);
      else h += renderBinaryFileBar(af, url);
    });
    h += '</div>';
    return h;
  };

  document.addEventListener('click', function (ev) {
    var zi = ev.target && ev.target.closest ? ev.target.closest('.merv-zoomable-image') : null;
    if (zi) {
      ev.preventDefault();
      openImageLightbox(zi.getAttribute('data-img-url') || zi.src, zi.getAttribute('data-img-name') || zi.alt);
      return;
    }
    var dl = ev.target && ev.target.closest ? ev.target.closest('[data-dl]') : null;
    if (dl) {
      ev.preventDefault();
      var u = dl.getAttribute('data-dl');
      var n = dl.getAttribute('data-name') || 'file';
      var a = document.createElement('a');
      a.href = u;
      a.download = n;
      a.click();
      return;
    }
    var op = ev.target && ev.target.closest ? ev.target.closest('[data-open]') : null;
    if (op) {
      ev.preventDefault();
      window.open(op.getAttribute('data-open'), '_blank');
    }
  });

  document.addEventListener('keydown', function (ev) {
    if (ev.key === 'Escape') closeImageLightbox();
  });
})();
